const employees = $input.all().map(item => item.json);

const request = $('Receive Employee Lookup Request').first().json;

const employeeId = String(request.employee_id ?? '')
  .trim().toLowerCase();

const fullName = String(request.full_name ?? '')
  .trim().toLowerCase();

const filtered = employees.filter(employee => {
  const matchesId = !employeeId ||
    String(employee.employee_id ?? '')
      .toLowerCase() === employeeId;

  const matchesName = !fullName ||
    String(employee.full_name ?? '')
      .toLowerCase().includes(fullName);

  return matchesId && matchesName;
});

return [{
  json: {
    success: true,
    total: filtered.length,
    filters: {
      employee_id: employeeId || null,
      full_name: fullName || null
    },
    employees: filtered.map(employee => ({
      employee_id: employee.employee_id,
      full_name: employee.full_name,
      department: employee.department,
      email: employee.email,
      role: employee.role,
      active: employee.active
    }))
  }
}];
